// @vitest-environment jsdom
/**
 * Genuine backend *output* is generated by selected station-access PR #20
 * via workspace_readiness.inspect() and workspace_diagnostics.project().
 * A missing producer fixture SKIPS this extra cross-owner lane only; dedicated
 * CI requires ZOG_WORKSPACE_CONTRACT_JSON and checks each immutable source.
 */
import { readFileSync } from 'node:fs'
import { afterEach, expect, it, vi } from 'vitest'
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter, Route, Routes } from 'react-router-dom'
import { api, type WorkspaceReadiness } from '../api'
import { VncPage } from '../pages/VncPage'
import { PersistentVncSessions } from './PersistentVncSessions'
import { VncSessionProvider } from './VncSessionProvider'

const contractPath = process.env.ZOG_WORKSPACE_CONTRACT_JSON
const run = contractPath ? it : it.skip
type Scenarios = Record<
  'current' | 'rfb_recovered' | 'stale_stage' | 'foreign_stage' |
  'runtime_replaced' | 'controller_unavailable',
  WorkspaceReadiness
>
const backend = contractPath
  ? JSON.parse(readFileSync(contractPath, 'utf8')) as Scenarios
  : null

function Viewer() {
  return <MemoryRouter initialEntries={['/vnc/workspace-one']}>
    <VncSessionProvider>
      <Routes><Route path="/vnc/:workspaceId" element={<VncPage />} /></Routes>
      <PersistentVncSessions />
    </VncSessionProvider>
  </MemoryRouter>
}
const check = (payload: WorkspaceReadiness, name: string) =>
  payload.diagnostics?.checks.find(entry => entry.condition === name)
afterEach(() => { cleanup(); vi.restoreAllMocks() })

run('actual backend API envelope separates current, foreign, stale and saved-grant evidence', () => {
  const c = backend!
  expect(c.current.read_only).toBe(true)
  expect(c.current.advisory).toBe(true)
  expect(c.current.diagnostics?.schema).toBe('station-workspace-diagnostics-v1')
  expect(check(c.current, 'x11-authorization')).toMatchObject({
    status: 'confirmed', code: 'ok', source: 'current-controller',
  })
  expect(check(c.current, 'rfb-availability')).toMatchObject({
    status: 'failed', code: 'rfb-invalid',
  })
  expect(check(c.current, 'browser-grant')).toMatchObject({
    status: 'confirmed', code: 'grant-record-current', source: 'saved-record',
  })
  expect(check(c.stale_stage, 'x11-authorization')?.status).toBe('unknown')
  expect(check(c.foreign_stage, 'rfb-availability')?.status).toBe('unknown')
  expect(check(c.runtime_replaced, 'accepted-runtime')?.status).not.toBe('confirmed')
  expect(check(c.runtime_replaced, 'browser-grant')?.status).toBe('unknown')
  expect(c.controller_unavailable.controller).toBe('unavailable')
  expect(c.controller_unavailable.diagnostics?.checks.every(x => x.status === 'unknown')).toBe(true)
  for (const payload of Object.values(c)) {
    const serialized = JSON.stringify(payload)
    expect(serialized).not.toContain('/protected/')
    expect(serialized).not.toContain('private/token')
    expect(serialized).not.toContain('bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb')
    expect(serialized).not.toContain('novnc_url')
    expect(serialized).not.toContain('token')
  }
})

run('controller replacement and stale proofs never remount the granted iframe or reset zoom', async () => {
  const c = backend!
  const grant = vi.spyOn(api, 'vncGrant').mockResolvedValue({
    token: 'viewer-private', expires_at: 'later', novnc_url: 'about:blank#grant-original',
  })
  const read = vi.spyOn(api, 'workspaceReadiness').mockResolvedValue(c.current)
  const view = render(<Viewer />)
  await waitFor(() => expect(view.container.querySelector('iframe')).not.toBeNull())
  const frame = view.container.querySelector('iframe')!
  fireEvent.click(screen.getByRole('button', { name: 'Zoom in' }))
  fireEvent.click(screen.getByRole('button', { name: 'Workspace status' }))
  await screen.findByLabelText('Workspace diagnostics')
  expect(screen.getByLabelText('Workspace diagnostics').textContent).toContain('rfb availability · failed')
  const next = async (payload: WorkspaceReadiness) => {
    read.mockResolvedValueOnce(payload)
    fireEvent.click(screen.getByRole('button', { name: 'Refresh status' }))
    await waitFor(() => expect(screen.getByLabelText('Workspace diagnostics').textContent)
      .toContain(payload.diagnostics!.checks.find(x => x.condition === 'accepted-runtime')!.code))
  }
  await next(c.runtime_replaced)
  expect(screen.getByLabelText('Workspace diagnostics').textContent).toContain('accepted runtime · unknown')
  await next(c.stale_stage)
  expect(screen.getByLabelText('Workspace diagnostics').textContent).toContain('x11 authorization · unknown')
  await next(c.rfb_recovered)
  expect(screen.getByLabelText('Workspace diagnostics').textContent).toContain('rfb availability · confirmed')
  expect(view.container.querySelector('iframe')).toBe(frame)
  expect(frame.getAttribute('src')).toBe('about:blank#grant-original')
  expect(screen.getByLabelText('Viewer zoom').textContent).toBe('125%')
  expect(grant).toHaveBeenCalledTimes(1)
})

run('backend outage does not grant access and explicit reconnect ignores a delayed prior grant', async () => {
  const c = backend!
  let oldGrant!: (value: Awaited<ReturnType<typeof api.vncGrant>>) => void
  const grant = vi.spyOn(api, 'vncGrant')
    .mockResolvedValueOnce({
      token: 'original-private', expires_at: 'later', novnc_url: 'about:blank#old',
    })
    .mockImplementationOnce(() => new Promise(resolve => { oldGrant = resolve }))
    .mockResolvedValueOnce({
      token: 'latest-private', expires_at: 'later', novnc_url: 'about:blank#latest',
    })
  const read = vi.spyOn(api, 'workspaceReadiness').mockResolvedValue(c.current)
  const view = render(<Viewer />)
  await waitFor(() => expect(view.container.querySelector('iframe')).not.toBeNull())
  const first = view.container.querySelector('iframe')
  fireEvent.click(screen.getByRole('button', { name: 'Zoom in' }))
  fireEvent.click(screen.getByRole('button', { name: 'Workspace status' }))
  await screen.findByLabelText('Workspace diagnostics')
  read.mockResolvedValueOnce(c.controller_unavailable)
  fireEvent.click(screen.getByRole('button', { name: 'Refresh status' }))
  await waitFor(() => expect(screen.getByLabelText('Workspace diagnostics').textContent)
    .toContain('controller unavailable'))
  expect((screen.getByRole('button', { name: 'Connect desktop' }) as HTMLButtonElement).disabled).toBe(true)
  expect(view.container.querySelector('iframe')).toBe(first)
  fireEvent.click(screen.getByRole('button', { name: 'Close viewer' }))
  expect(view.container.querySelector('iframe')).toBeNull()
  fireEvent.click(screen.getByRole('button', { name: /^Connect$/ }))
  await waitFor(() => expect(grant).toHaveBeenCalledTimes(2))
  // Explicit close overtakes pending reconnection: stale grant ignored.
  fireEvent.click(screen.getByRole('button', { name: 'Connect' }))
  // Need a matching close to invalidate the pending response.
  // A new grant can only be accepted after the explicit next request.
  oldGrant({ token: 'outdated-private', expires_at: 'later', novnc_url: 'about:blank#late' })
  await waitFor(() => expect(view.container.querySelector('iframe')?.getAttribute('src')).not.toBe('about:blank#late'))
  expect(screen.getByLabelText('Viewer zoom').textContent).toBe('125%')
})
